 9→export async function PATCH(request: Request, context: RouteContext) {
10→  const user = await getCurrentUser();
11→  if (!user) {
12→    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
13→  }
14→  if (!["SUPER_ADMIN", "ADMIN"].includes(user.role)) {
15→    return NextResponse.json({ message: "Forbidden" }, { status: 403 });
16→  }
17→  const body = (await request.json()) as {
18→    status?: string;
19→    nextAction?: string;
20→  };
21→  const { id } = await context.params;
22→
23→  if (!body.status || !body.nextAction) {
24→    return NextResponse.json(
25→      { message: "status and nextAction are required" },
26→      { status: 400 },
27→    );
28→  }
29→
30→  const updated = updateRecruitmentRequest(Number(id), {
31→    status: body.status,
32→    nextAction: body.nextAction,
33→  });
34→
35→  if (!updated) {
36→    return NextResponse.json({ message: "Not found" }, { status: 404 });
37→  }
38→
39→  return NextResponse.json(updated);
40→}
